(5880993, 856290, 97225, '<td valign="top">Beautifully captured. The light on the dancer is great and so is the composition.</td>', 'Beautifully captured. The light on the dancer is great and so is the composition.', '2010-02-25 17:19:31.000000', NULL, 1),
