(5884342, 856027, 33361, '<td valign="top">rofl</td>', 'rofl', '2010-03-01 02:18:46.000000', NULL, 1),
(5884429, 856150, 113156, '<td valign="top">this tells a story, i really like it, Bravo.</td>', 'this tells a story, i really like it, Bravo.', '2010-03-01 03:34:41.000000', NULL, 1),
(5884959, 856191, 63269, '<td valign="top">This is one of my favorites in this challenge. The visual simplicity of neutral colors makes this an attractive image, and I think the concept of ''dance,'' is more passionately and realistically portrayed here than in any of the other challenge images. Something about how the viewer cannot see the boy''s face gives a sense that he is lost in expression of his emotions, giving this image a poignant honesty. Yes, the staged portraits of cute little girls in flowery ballet costumes will probably get the high scores - but it''s images like these that encourage me to keep hunting for more of the good stuff - it <i>is </i>out here.  :)</td>', 'This is one of my favorites in this challenge. The visual simplicity of neutral colors makes this an attractive image, and I think the concept of ''dance,'' is more passionately and realistically portrayed here than in any of the other challenge images. Something about how the viewer cannot see the boy''s face gives a sense that he is lost in expression of his emotions, giving this image a poignant honesty. Yes, the staged portraits of cute little girls in flowery ballet costumes will probably get the high scores - but it''s images like these that encourage me to keep hunting for more of the good stuff - it is out here.  :)', '2010-03-01 12:18:17.000000', NULL, 1),
(5884964, 856299, 63269, '<td valign="top">If only that little gray sliver were cropped on the left side of the image.... but otherwise I like this a lot. The bold black and white contrast is really cool!</td>', 'If only that little gray sliver were cropped on the left side of the image.... but otherwise I like this a lot. The bold black and white contrast is really cool!', '2010-03-01 12:20:43.000000', NULL, 1),
